import { Component } from '@angular/core';
import { DataViewSectionComponent } from "../../../shared/data-view-section/data-view.component";
import { SolicitudApoyo } from '../../../models/solicitud.apoyo';
import { SolicitudApoyoService } from '../../../controllers/solicitud.apoyo.service';
import { ActivatedRoute } from '@angular/router';
import { SolicitudApoyoModalidadService } from '../../../controllers/solicitud.apoyo.modalidad.service';
import { CurrencyPipe } from '@angular/common';
import { SolicitudApoyoModalidad } from '../../../models/solicitud.apoyo.modalidad';
import { UtilsService } from '../../../services/utils.service';
import { ApoyoTipoInversion } from '../../../models/apoyo.tipo.inversion';

@Component({
    selector: 'app-validar-apoyo',
    imports: [
    CurrencyPipe,
    DataViewSectionComponent
],
    templateUrl: './validar-apoyo.component.html',
    styleUrl: './validar-apoyo.component.css'
})
export class ValidarApoyoComponent {
  solicitudApoyo?: SolicitudApoyo

  modalidadActual?: SolicitudApoyoModalidad

  apoyoTiposInversiones:ApoyoTipoInversion[]=[]

  constructor(
    public solicitudApoyoController: SolicitudApoyoService,
    private route: ActivatedRoute,
    public utils: UtilsService,
  ){}

  ngOnInit(){
    this.route.params.subscribe(async (params) =>{
      const id= params['apoyo_id']
      if(id){
        this.solicitudApoyo= await this.solicitudApoyoController.find(id,[
          "programasApoyos",
          'datosPersonales',
          "apoyosTiposInversiones.apoyosTiposInversionesDetalles",
          "solicitudesApoyosModalidades.modalidadesMinistraciones.modalidades",
          "solicitudesApoyosModalidades.solicitudesApoyosModalidadesCotizaciones.apoyosProveedores",
          "solicitudesApoyosModalidades.solicitudesApoyosModalidadesDocumentos.modalidadesMinistracionesDocumentos.documentos",
          "apoyosTiposInversionesDetalles",
        ])
        this.apoyoTiposInversiones= this.solicitudApoyoController.tiposInversionesActuales(this.solicitudApoyo)

        this.modalidadActual= this.solicitudApoyoController.modalidadActual(this.solicitudApoyo)
        console.log(this.solicitudApoyo)
      }
    })
  }

  totalInversion(){
    return this.apoyoTiposInversiones.reduce((acc,tipo)=>{
      return acc+this.totalTipo(tipo)
    },0)??0
  }

  totalTipo(tipo:ApoyoTipoInversion|undefined){
    if(!tipo?.apoyos_tipos_inversiones_detalles) return 0
    return tipo.apoyos_tipos_inversiones_detalles.reduce((acc,detalle)=> acc+detalle.monto_solicitado,0)
  }
}
