import { Component, Input } from '@angular/core';
import { SolicitudApoyo } from '../../../models/solicitud.apoyo';
import { SolicitudApoyoModalidad } from '../../../models/solicitud.apoyo.modalidad';
import { CotizacionFactura } from '../../../models/cotizacion.factura';
import { CotizacionFacturaService } from '../../../controllers/cotizacion.factura.service';
import { FormGroupComponent } from "../../../shared/generic-form/form-group/form-group.component";

import { SolicitudApoyoModalidadCotizacion } from '../../../models/solicitud.apoyo.modalidad.cotizacion';
import { FileInputComponent } from "../../../shared/file-input/file-input.component";
import { SolicitudApoyoService } from '../../../controllers/solicitud.apoyo.service';
import { UtilsService } from '../../../services/utils.service';

@Component({
    selector: 'app-concluir-apoyo',
    imports: [
    FormGroupComponent,
    FileInputComponent
],
    templateUrl: './concluir-apoyo.component.html',
    styleUrl: './concluir-apoyo.component.css'
})
export class ConcluirApoyoComponent {
  @Input() solicitudApoyo!: SolicitudApoyo
  @Input() solicitudModalidadActual!: SolicitudApoyoModalidad

  constructor(
    public solicitudApoyoController: SolicitudApoyoService,
    public cotizacionFacturaController: CotizacionFacturaService,
    public utils: UtilsService,
  ) { }

  /**
   * Adds a new invoice (factura) to a specific quotation (cotización) within the current support request modality.
   * If the quotation does not already have an array of invoices, it initializes one.
   *
   * @param cotizacion - The quotation to which the invoice will be added.
   * @returns {Promise<void>} - A promise that resolves when the invoice is successfully added.
   */
  async addFactura(cotizacion: SolicitudApoyoModalidadCotizacion): Promise<void> {
    // Initialize the invoices array if it doesn't exist
    if (!cotizacion.cotizaciones_facturas) {
      cotizacion.cotizaciones_facturas = [];
    }

    // Create a new invoice associated with the quotation
    const nuevaFactura = await this.cotizacionFacturaController.new({
      solicitudes_apoyos_modalidades_cotizacion_id: cotizacion.id
    });

    // If the invoice is successfully created, add it to the quotation's invoices array
    if (nuevaFactura) {
      cotizacion.cotizaciones_facturas.push(nuevaFactura);
    }
  }

  /**
   * Deletes an invoice (factura) from a specific quotation (cotización) within the current support request modality.
   * If the quotation does not have any invoices, the function returns early.
   *
   * @param cotizacion - The quotation from which the invoice will be deleted.
   * @param factura - The invoice to be deleted.
   * @returns {Promise<void>} - A promise that resolves when the invoice is successfully deleted.
   */
  public async deleteFactura(cotizacion: SolicitudApoyoModalidadCotizacion, factura: CotizacionFactura): Promise<void> {
    // Return early if there are no invoices to delete
    if (!cotizacion.cotizaciones_facturas) {
      return;
    }

    // Attempt to delete the invoice
    const resultado = await this.cotizacionFacturaController.switch(factura);

    // If the deletion is successful, remove the invoice from the quotation's invoices array
    if (resultado) {
      const indiceFactura = cotizacion.cotizaciones_facturas.indexOf(factura);
      if (indiceFactura !== -1) {
        cotizacion.cotizaciones_facturas.splice(indiceFactura, 1);
      }
    }
  }

  public seSubioFacturas():boolean{
    return !!(this.solicitudModalidadActual.solicitudes_apoyos_modalidades_cotizaciones?.every(cot => cot.cotizaciones_facturas?.every(fac => fac.documento_url)) 
    && this.solicitudModalidadActual.solicitudes_apoyos_modalidades_cotizaciones.every(cot => cot.cotizaciones_facturas?.length))
  }
}
