import { Component, Input, SimpleChanges } from '@angular/core';
import { SolicitudApoyo } from '../../../models/solicitud.apoyo';
import { SolicitudApoyoModalidad } from '../../../models/solicitud.apoyo.modalidad';
import { FileInputComponent } from "../../../shared/file-input/file-input.component";

import { SolicitudApoyoModalidadCotizacion } from '../../../models/solicitud.apoyo.modalidad.cotizacion';
import { ApoyoProveedor } from '../../../models/apoyo.proveedor';
import { UtilsService } from '../../../services/utils.service';
import { ApoyosCartaInstruccionesService } from '../../../services/documentosLegales/contratos/apoyos_carta_de_instruccion.service';
import { SolicitudApoyoService } from '../../../controllers/solicitud.apoyo.service';
import { SolicitudApoyoModalidadCotizacionService } from '../../../controllers/solicitud.apoyo.modalidad.cotizacion.service';
import { SolicitudApoyoModalidadService } from '../../../controllers/solicitud.apoyo.modalidad.service';

@Component({
    selector: 'app-preliberar-apoyo',
    imports: [
    FileInputComponent
],
    templateUrl: './preliberar-apoyo.component.html',
    styleUrl: './preliberar-apoyo.component.css'
})
export class PreliberarApoyoComponent {
  @Input() solicitudApoyo!:SolicitudApoyo
  @Input() solicitudModalidadActual!: SolicitudApoyoModalidad
  dataSource:{
    proveedor: ApoyoProveedor 
    cotizaciones:SolicitudApoyoModalidadCotizacion[]
  }[]=[]

  @Input() liberar=false

  constructor(
    public utils: UtilsService,
    public solicitudApoyoController: SolicitudApoyoService,
    private solicitudApoyoModalidadController: SolicitudApoyoModalidadService,
    private cotizacionController:SolicitudApoyoModalidadCotizacionService,
    public cartaInstruccion: ApoyosCartaInstruccionesService,
  ){}

  ngOnInit(){
    this.agruparProveedores()
  }

  ngOnChanges(changes:SimpleChanges){
    if(changes['solicitudApoyo'] || changes['solicitudModalidadActual']){
      this.agruparProveedores()
    }
  }

  agruparProveedores(){
    this.dataSource=[]
    this.solicitudModalidadActual.solicitudes_apoyos_modalidades_cotizaciones?.forEach((cotizacion)=>{
      const find= this.dataSource.find((row)=> row.proveedor.id === cotizacion.apoyos_proveedores?.id)
      if(find){
        find.cotizaciones.push(cotizacion)
        return
      }
      this.dataSource.push({
        proveedor:cotizacion.apoyos_proveedores!,
        cotizaciones:[cotizacion]
      })
    })
    console.log(this.dataSource)
  }

  saveUrls(cotizaciones:SolicitudApoyoModalidadCotizacion[], url:string){
    cotizaciones.forEach((cot)=>{
      cot.carta_instruccion_url=url
      this.cotizacionController.update(cot.id,cot)
    })
  }

  saveSpeiUrl(cotizaciones:SolicitudApoyoModalidadCotizacion[], url:string){
    cotizaciones.forEach((cot)=>{
      cot.spei_url=url
      this.cotizacionController.update(cot.id,cot)
    })
  }

  todosDocumentosSubidos(proveedor?:ApoyoProveedor):boolean{
    if(!this.liberar){
      if(proveedor){
        return this.dataSource.filter((prov)=> prov.proveedor.id==proveedor.id).every((prov)=> prov.cotizaciones.every((cot)=> cot.carta_instruccion_url))
      }
      return this.dataSource.every((prov)=> prov.cotizaciones.every((cot)=> cot.carta_instruccion_url))
    }
    if(proveedor){
      return this.dataSource.filter((prov)=> prov.proveedor.id==proveedor.id).every((prov)=> prov.cotizaciones.every((cot)=> cot.spei_url))
    }
    return this.dataSource.every((prov)=> prov.cotizaciones.every((cot)=> cot.spei_url))
  }
}
