import { Routes } from "@angular/router";
import { ListApoyosComponent } from "./list-apoyos/list-apoyos.component";
import { FormApoyosComponent } from "./form-apoyos/form-apoyos.component";
import { ValidarApoyoComponent } from "./validar-apoyo/validar-apoyo.component";

export const apoyosRoutes:Routes =[
    { path:'', redirectTo:'list', pathMatch:'full' },
    { path:'validar/:apoyo_id', component:ValidarApoyoComponent },
    {
        title:'Apoyos',
        path:'list',
        component:ListApoyosComponent,
    },
    {
        title:'Pendientes',
        path:'pendientes',
        component:ListApoyosComponent,
    },
    {
        title:'Verificación',
        path:'verificados',
        component:ListApoyosComponent,
    },
    {
        title:'Dictaminación',
        path:'dictaminacion',
        component:ListApoyosComponent,
    },
    {
        title:'Preliberación',
        path:'preliberacion',
        component:ListApoyosComponent,
    },
    {
        title:'Liberación',
        path:'liberacion',
        component:ListApoyosComponent,
    },
    {
        title:'Conclusión',
        path:'conclusion',
        component:ListApoyosComponent,
    },
    {
        title:'Apoyos Formulario',
        path:'editar/:apoyo_id',
        component:FormApoyosComponent,
        loadChildren: () => import('./form-apoyos/form.apoyos.routes').then(m=> m.formApoyosRoutes),
    },
]