import { Component } from '@angular/core';
import { AdvancedSearch, AdvancedSearchFilter, HeaderButton, RowButton, RowButtonClickEvent, TablaComponent, TableDefinition } from "../../../shared/tabla/tabla.component";
import { FormularioFlotanteComponent } from "../../../shared/formulario-flotante/formulario-flotante.component";
import { SelectFieldComponent } from "../../../shared/generic-form/select-field/select-field.component";
import { AutocompleteFieldComponent } from "../../../shared/generic-form/autocomplete-field/autocomplete-field.component";
import { Option } from '../../../shared/generic-form/form-field/form-field.component';
import { ActivatedRoute, Router } from '@angular/router';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';
import { SolicitudApoyo } from '../../../models/solicitud.apoyo';
import { SolicitudApoyoService } from '../../../controllers/solicitud.apoyo.service';
import { SolicitudApoyoModalidad } from '../../../models/solicitud.apoyo.modalidad';

import { SolicitudApoyoModalidadService } from '../../../controllers/solicitud.apoyo.modalidad.service';
import { PreliberarApoyoComponent } from "../preliberar-apoyo/preliberar-apoyo.component";
import { ConcluirApoyoComponent } from "../concluir-apoyo/concluir-apoyo.component";
import { DatoPersonal } from '../../../models/dato.personal.model';
import { UtilsService } from '../../../services/utils.service';

const TABLA_DEF: TableDefinition = {
  columns: [
    'id',
    {
      key: 'datos_personales',
      header: 'Nombre Solicitante',
      function: (row: DatoPersonal, utils: UtilsService) => {
        return utils.nombreClienteFromDatosPersonales(row)
      }
    },
    'nombre_comercial',
    {
      key: 'solicitudes_apoyos_modalidades',
      header: 'Modalidad Actual',
      function: (modalidades: SolicitudApoyoModalidad[]) => {
        if (modalidades.length == 0) return 'N/A';
        return modalidades[modalidades.length - 1].modalidades_ministraciones?.modalidades?.nombre
      }
    },
    {
      key: 'solicitudes_apoyos_modalidades',
      header: 'Estado',
      function: (modalidades: SolicitudApoyoModalidad[]) => {
        if (modalidades.length == 0) return 'N/A';
        return modalidades[modalidades.length - 1].estado
      }
    },
    {
      key: 'solicitudes_apoyos_modalidades',
      header: 'Total Modalidades',
      function: (modalidades: SolicitudApoyoModalidad[]) => {
        return modalidades.length.toString()
      }
    },
    {
      key: 'usuarios',
      header: 'Creado Por',
      subKey: 'nombre',
    },
    'created_at',
  ]
}

const BASE_FILTERS: AdvancedSearch = [
  {
    label: 'Municipio:',
    apiUrl: 'api/sucursales',
    keyList: 'id',
    keyDetalle: 'nombre',
    key: 'sucursal_id',
    placeholder: 'Ingresa una sucursal...',
    inputGroup: true,
  },
  {
    key: 'datosPersonales',
    label: 'Curp Solicitante',
    conditionals: [],
    andConditionals: [
      {
        key: 'curp',
        operator: 'LIKE',
      }
    ],
    type: 'text'
  },
  {
    key: 'solicitudesApoyosModalidades.modalidadesMinistraciones.modalidades',
    apiUrl: 'api/modalidades',
    keyList: 'id',
    keyDetalle: 'nombre',
    label: 'Modalidad',
    conditionals: [
      {
        key: 'id',
        operator: '=',
      }
    ]
  },
  {
    key: 'solicitudesApoyosModalidades',
    label: 'Estado',
    conditionals: [],
    andConditionals: [
      {
        key: 'estado',
        operator: '=',
      }
    ],
    options: ['CAPTURANDO', 'CAPTURA COMPLETA', 'VERIFICADO', 'SESION ASIGNADA', 'LIBERADO', 'CONCLUIDO']
  },
]


@Component({
    selector: 'app-list-apoyos',
    imports: [
    TablaComponent,
    FormularioFlotanteComponent,
    SelectFieldComponent,
    AutocompleteFieldComponent,
    PreliberarApoyoComponent,
    ConcluirApoyoComponent
],
    templateUrl: './list-apoyos.component.html',
    styleUrl: './list-apoyos.component.css'
})
export class ListApoyosComponent {
  tabla = TABLA_DEF
  baseFilters = BASE_FILTERS
  show: boolean = false
  edit: Partial<SolicitudApoyo> = {}
  sucursales: Option[] = []
  title = 'Solicitudes de Apoyo'
  extraData = {
    conditionals: JSON.stringify([
      ['created_at', '>=', (new Date()).getFullYear() + '-' + '01-01'],
      ['created_at', '<=', (new Date()).getFullYear() + '-' + '12-31'],
      ['deleted_at', 'IS NULL', null],
    ])
  }

  tableAdvancedFilters: AdvancedSearchFilter[] = []

  rowButtons: RowButton[] = []
  headerButtons: HeaderButton[] = []

  actualPath: string = ''

  rowEdit?: SolicitudApoyo
  modalidadActual?: SolicitudApoyoModalidad

  showDictaminar = false
  showPreliberar = false
  showLiberar = false
  showConclusion = false

  constructor(
    public solicitudApoyoController: SolicitudApoyoService,
    public modalidadContrller: SolicitudApoyoModalidadService,
    private route: ActivatedRoute,
    private router: Router,
    private storage: LocalStorageService,
    public utils: UtilsService,
  ) {
    const usuario = this.storage.getPerfil()
    this.edit.sucursal_id = usuario.sucursal_id
  }

  ngOnInit() {
    this.initSucursales()

    this.route.url.subscribe((url) => {
      this.updateFilters(url[0].path)
    })
  }

  onRowButtonClick(event: RowButtonClickEvent<SolicitudApoyo>) {
    this.rowEdit = event.row
    this.setModalidadActual()

    switch (event.key) {
      case 'validar':
        this.router.navigate(['/main/apoyos/validar', event.row.id])
        break;
      case 'dictaminar':
        this.showDictaminar = true
        break;
      case 'preliberar':
        this.showPreliberar = true
        break;
      case 'liberar':
        this.showLiberar = true
        break;
      case 'conclusion':
        this.showConclusion = true
    }
  }

  onHeaderButtonClick(key: string) {
    switch (key) {
      case 'pendientes':
        this.title = 'Apoyos Pendientes'
        this.tableAdvancedFilters = [
          {
            relation: 'solicitudesApoyosModalidades',
            conditionals: [],
            andConditionals: [
              ['estado', '=', 'CAPTURANDO']
            ]
          },
        ]
        break;
      case 'capturados':
        this.title = 'Apoyos Capturados'
        this.tableAdvancedFilters = [
          {
            relation: 'solicitudesApoyosModalidades',
            conditionals: [],
            andConditionals: [
              ['estado', '=', 'CAPTURA COMPLETA']
            ]
          },
        ]
        break;
      case 'verificados':
        this.title = 'Apoyos Verificados'
        this.tableAdvancedFilters = [
          {
            relation: 'solicitudesApoyosModalidades',
            conditionals: [],
            andConditionals: [
              ['estado', '=', 'VERIFICADO']
            ]
          },
        ]
        break;
      case 'dictaminacion':
        this.title = 'Apoyos Dictaminados'
        this.tableAdvancedFilters = [
          {
            relation: 'solicitudesApoyosModalidades',
            conditionals: [],
            andConditionals: [
              ['estado', '=', 'SESION ASIGNADA']
            ]
          },
        ]
        break;
      case 'liberacion':
        this.title = 'Apoyos Liberados'
        this.tableAdvancedFilters = [
          {
            relation: 'solicitudesApoyosModalidades',
            conditionals: [
              ['estado', '=', 'LIBERADO'],
              ['estado', '=', 'INCONCLUSO']
            ],
            andConditionals: []
          },
        ]
        break;
      case 'conclusion':
        this.title = 'Apoyos Concluidos'
        this.tableAdvancedFilters = [
          {
            relation: 'solicitudesApoyosModalidades',
            conditionals: [],
            andConditionals: [
              ['estado', '=', 'CONCLUIDO']
            ]
          },
        ]
        break;
    }
  }

  private updateFilters(path: string) {
    this.actualPath = path
    switch (path) {
      case 'pendientes':
        this.applyPendientesFilters()
        break;
      case 'verificados':
        this.applyVerificadosFilters()
        break;
      case 'dictaminacion':
        this.applyDictaminadosFilters()
        break;
      case 'liberacion':
        this.applyLiberacionFilters()
        break;
      case 'conclusion':
        this.applyConclusionFilters()
    }
  }

  private applyPendientesFilters() {
    this.title = 'Apoyos Pendientes'
    this.headerButtons = [
      {
        key: 'pendientes',
        text: 'Pendientes',
      },
      {
        key: 'capturados',
        text: 'Capturados',
      },
    ]
    this.tableAdvancedFilters = [
      {
        relation: 'solicitudesApoyosModalidades',
        conditionals: [],
        andConditionals: [
          ['estado', '=', 'CAPTURANDO']
        ]
      },
    ]
  }

  private applyVerificadosFilters() {
    this.title = 'Apoyos Capturados'
    this.headerButtons = [
      {
        key: 'capturados',
        text: 'Capturados',
      },
      {
        key: 'verificados',
        text: 'Verificados',
      }
    ]
    this.rowButtons = [
      {
        key: 'validar',
        style: {
          button: 'btn btn-secondary',
        },
        text: 'Validar'
      }
    ]
    this.tableAdvancedFilters = [
      {
        relation: 'solicitudesApoyosModalidades',
        conditionals: [],
        andConditionals: [
          ['estado', '=', 'CAPTURA COMPLETA']
        ]
      },
    ]
  }

  private applyDictaminadosFilters() {
    this.title = 'Apoyos Verificados'
    this.headerButtons = [
      {
        key: 'verificados',
        text: 'Verificados',
      },
      {
        key: 'dictaminacion',
        text: 'Dictaminados',
      },
    ]
    this.rowButtons = [
      {
        key: 'dictaminar',
        style: {
          button: 'btn btn-secondary',
        },
        text: 'Dictaminar'
      }
    ]
    this.tableAdvancedFilters = [
      {
        relation: 'solicitudesApoyosModalidades',
        conditionals: [],
        andConditionals: [
          ['estado', '=', 'VERIFICADO']
        ]
      },
    ]

  }


  private applyLiberacionFilters() {
    this.title = 'Apoyos Dictaminados'
    this.headerButtons = [
      {
        key: 'dictaminacion',
        text: 'Dictaminados',
      },
      {
        key: 'liberacion',
        text: 'Liberados',
      }
    ]
    this.rowButtons = [
      {
        key: 'liberar',
        style: {
          button: 'btn btn-secondary',
        },
        text: 'Liberar'
      }
    ]
    this.tableAdvancedFilters = [
      {
        relation: 'solicitudesApoyosModalidades',
        conditionals: [],
        andConditionals: [
          ['estado', '=', 'SESION ASIGNADA']
        ],
      },
    ]
  }

  private applyConclusionFilters() {
    this.title = 'Apoyos Liberados'
    this.headerButtons = [
      {
        key: 'liberacion',
        text: 'Liberados',
      },
      {
        key: 'conclusion',
        text: 'Concluidos',
      }
    ]
    this.rowButtons = [
      {
        key: 'conclusion',
        style: {
          button: 'btn btn-secondary',
        },
        text: 'Concluir'
      }
    ]
    this.tableAdvancedFilters = [
      {
        relation: 'solicitudesApoyosModalidades',
        conditionals: [
          ['estado', '=', 'LIBERADO'],
          ['estado', '=', 'INCONCLUSO']
        ],
        andConditionals: [],
      },
    ]
  }

  initSucursales() {
    const userLogin = this.storage.getUser()
    this.sucursales = userLogin.perfiles.map((perfil) => {
      return {
        value: perfil.sucursales.id,
        label: perfil.sucursales.nombre
      }
    })
  }

  async onSubmit() {
    const res = await this.solicitudApoyoController.new(this.edit)
    console.log(res);
    if (res) {
      this.router.navigate(['../editar', res.id], { relativeTo: this.route })
    }
    return
  }

  public async dictaminar() {
    if (!this.modalidadActual) return;
    await this.modalidadContrller.update(this.modalidadActual.id, this.modalidadActual)
    await this.solicitudApoyoController.avanzarEstado(this.modalidadActual)
  }

  setModalidadActual() {
    this.modalidadActual = this.rowEdit!.solicitudes_apoyos_modalidades![this.rowEdit!.solicitudes_apoyos_modalidades!.length - 1]
  }
}
